import pandas as pd
import numpy as np
from datetime import timedelta

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Extract the high_ts watermark value
    high_ts = watermark["high_ts"].iloc[0]

    # Filter events that are strictly greater than the watermark
    new_events = cdc_events[cdc_events["event_ts"] > high_ts].copy()

    # If no new events, return the target snapshot as-is
    if len(new_events) == 0:
        return {"new_snapshot": target_snapshot}

    # Sort events by user_id, then by event_ts, then by event_seq for deterministic processing
    new_events = new_events.sort_values(by=["user_id", "event_ts", "event_seq"]).reset_index(drop=True)

    # Create a dictionary to track the current state of each user
    # Key: user_id, Value: {email, status, status_ts}
    user_state = {}

    # Initialize user_state from target_snapshot
    for _, row in target_snapshot.iterrows():
        user_id = row["user_id"]
        user_state[user_id] = {
            "email": row["email"],
            "status": row["status"],
            "status_ts": row["status_ts"]
        }

    # Process each event in order
    for _, event in new_events.iterrows():
        user_id = event["user_id"]
        event_ts = event["event_ts"]
        op = event["op"]
        email = event["email"]

        # Get current state or initialize if new user
        if user_id not in user_state:
            current_status = "ACTIVE"
            current_status_ts = None
            current_email = None
        else:
            current_status = user_state[user_id]["status"]
            current_status_ts = user_state[user_id]["status_ts"]
            current_email = user_state[user_id]["email"]

        if op == "D":
            # Soft delete: set status to DELETED, preserve email, update status_ts
            user_state[user_id] = {
                "email": current_email,
                "status": "DELETED",
                "status_ts": event_ts
            }
        elif op == "U":
            # Update operation
            if current_status == "DELETED":
                # User is currently deleted - check resurrection window
                # Resurrection only if event_ts is STRICTLY MORE than 7 days after status_ts
                if current_status_ts is not None:
                    resurrection_threshold = current_status_ts + timedelta(days=7)
                    if event_ts > resurrection_threshold:
                        # Resurrection allowed
                        user_state[user_id] = {
                            "email": email,
                            "status": "ACTIVE",
                            "status_ts": event_ts
                        }
                    # else: update is discarded (deletion is sticky)
                else:
                    # Edge case: status is DELETED but no status_ts (shouldn't happen)
                    user_state[user_id] = {
                        "email": email,
                        "status": "ACTIVE",
                        "status_ts": event_ts
                    }
            else:
                # User is ACTIVE or new: upsert
                user_state[user_id] = {
                    "email": email,
                    "status": "ACTIVE",
                    "status_ts": event_ts
                }

    # Build the new snapshot from user_state
    result_rows = []
    for user_id, state in user_state.items():
        result_rows.append({
            "user_id": user_id,
            "email": state["email"],
            "status": state["status"],
            "status_ts": state["status_ts"]
        })

    new_snapshot = pd.DataFrame(result_rows)

    # Ensure correct dtypes
    if len(new_snapshot) > 0:
        new_snapshot["user_id"] = new_snapshot["user_id"].astype("int64")
        new_snapshot["email"] = new_snapshot["email"].astype("object")
        new_snapshot["status"] = new_snapshot["status"].astype("object")
        new_snapshot["status_ts"] = pd.to_datetime(new_snapshot["status_ts"], utc=False)
    else:
        new_snapshot = pd.DataFrame(columns=["user_id", "email", "status", "status_ts"])
        new_snapshot = new_snapshot.astype({
            "user_id": "int64",
            "email": "object",
            "status": "object",
            "status_ts": "datetime64[us]"
        })

    return {"new_snapshot": new_snapshot}
